public class MistSpan {
    static final int ALIGN = 32;
    static final int PIN_SIZE = 48;
    static final byte[] MAGIC = new byte[] {'P', 'N', '0', '1'};

    public static final class Row {
        public final byte[] id;
        public final byte[] payload;

        Row(byte[] id, byte[] payload) {
            this.id = id;
            this.payload = payload;
        }
    }

    public static Row row(byte[] pins, byte[] blob, int pos) throws Exception {
        if (pos < 0 || pos > pins.length - PIN_SIZE) return null;
        ByteBuffer bb = ByteBuffer.wrap(pins, pos, PIN_SIZE);
        byte[] magic = new byte[4];
        bb.get(magic);
        if (!Arrays.equals(magic, MAGIC)) return null;
        long off = bb.getLong();
        int len = bb.getInt();
        int checksum = bb.getInt();
        byte[] id = new byte[16];
        bb.get(id);
        if (off < 0 || len < 0 || off > Integer.MAX_VALUE) return null;
        long raw = 4L + len;
        long padded = raw + ((ALIGN - (raw % ALIGN)) % ALIGN);
        if (padded > Integer.MAX_VALUE || off > blob.length || padded > blob.length - off) return null;
        int at = (int) off;
        if (ByteBuffer.wrap(blob, at, 4).getInt() != len) return null;
        byte[] payload = Arrays.copyOfRange(blob, at + 4, at + 4 + len);
        CRC32 crc = new CRC32();
        crc.update(payload);
        if ((int) crc.getValue() != checksum) return null;
        byte[] digest = MessageDigest.getInstance("SHA-256").digest(payload);
        if (!Arrays.equals(id, Arrays.copyOf(digest, 16))) return null;
        return new Row(id, payload);
    }

    public static byte[] find(Path silo, byte[] wanted) throws Exception {
        if (wanted == null || wanted.length != 16) return null;
        Path pp = silo.resolve("pin.bin");
        Path bp = silo.resolve("blob.bin");
        byte[] pins = Files.exists(pp) ? Files.readAllBytes(pp) : new byte[0];
        byte[] blob = Files.exists(bp) ? Files.readAllBytes(bp) : new byte[0];
        for (int pos = 0; pos + PIN_SIZE <= pins.length; pos += PIN_SIZE) {
            Row r = row(pins, blob, pos);
            if (r != null && Arrays.equals(r.id, wanted)) return r.payload;
        }
        return null;
    }

    public static byte[] tint_k(Path silo, byte[] wanted) throws Exception {
        byte[] payload = find(silo, wanted);
        return payload == null ? new byte[0] : payload;
    }
